describe("StoreApi content-encoded query parameters", () => {
  async function captureSearch(q: PhotoMetadata): Promise<string> {
    let capturedUrl = "";
    const server = http.createServer((req, res) => {
      capturedUrl = req.url ?? "";
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end("[]");
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    try {
      const addr = server.address() as { port: number };
      const searchApi = new StoreApi(
        undefined,
        Configuration.builder()
          .baseUrl(`http://127.0.0.1:${addr.port}`)
          .build(),
      );
      await searchApi.searchStore({ q });
      return capturedUrl;
    } finally {
      server.close();
    }
  }

  test("bhv operations 097 searchStore sends q as the ObjectSerializer JSON, unescaped and percent-encoded", async () => {
    const url = await captureSearch(
      new PhotoMetadata({ caption: "a/b<\u00e9" }),
    );

    expect(url).toContain("q=%7B%22caption%22%3A%22a%2Fb%3C%C3%A9%22");
  });

  let hits = 0;

  async function captureRequest(
    call: (storeApi: StoreApi) => Promise<unknown>,
  ): Promise<string> {
    let capturedUrl = "";
    const server = http.createServer((req, res) => {
      hits++;
      capturedUrl = req.url ?? "";
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(capturedUrl.startsWith("/store/search") ? "[]" : '{"id":1}');
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    try {
      const addr = server.address() as { port: number };
      await call(
        new StoreApi(
          undefined,
          Configuration.builder()
            .baseUrl(`http://127.0.0.1:${addr.port}`)
            .build(),
        ),
      );
      return capturedUrl;
    } finally {
      server.close();
    }
  }

  test("searchStore expands a Set parameter like an array", async () => {
    const url = await captureRequest((s) =>
      s.searchStore({ labels: new Set(["red", "blue"]) }),
    );

    expect(
      new URL(url, "http://localhost").searchParams.getAll("labels").sort(),
    ).toEqual(["blue", "red"]);
  });

  test.each([
    ["10:30:00.123456789", "at=10%3A30%3A00.123"],
    ["10:30:00", "at=10%3A30%3A00"],
  ])("searchStore sends the time %s as %s", async (time, expected) => {
    const url = await captureRequest((s) =>
      s.searchStore({ at: Temporal.PlainTime.from(time) }),
    );

    expect(url).toContain(expected);
    expect(url).not.toContain(`${expected}0`);
  });

  test("bhv operations 124 getOrderByTrackingId puts the lowercase uuid in the path", async () => {
    const url = await captureRequest((s) =>
      s.getOrderByTrackingId(uuid("E621E1F8-C36C-495A-93FC-0C247A3E6E5F")),
    );

    expect(url).toBe(
      "/store/order/by-tracking/e621e1f8-c36c-495a-93fc-0c247a3e6e5f",
    );
  });

  test("bhv operations 111 getOrderByTrackingId rejects a malformed uuid before sending a request", async () => {
    hits = 0;
    const call = captureRequest((s) =>
      s.getOrderByTrackingId("not-a-uuid" as UUID),
    );

    await expect(call).rejects.toThrow(
      new TypeError(
        `Parameter 'trackingId' is not a canonical UUID: "not-a-uuid"`,
      ),
    );
    expect(hits).toBe(0);
  });

  test("bhv operations 121 searchStore sends the content header X-Filter as the ObjectSerializer JSON", async () => {
    let capturedHeader: string | string[] | undefined;
    const server = http.createServer((req, res) => {
      capturedHeader = req.headers["x-filter"];
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end("[]");
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    try {
      const addr = server.address() as { port: number };
      await new StoreApi(
        undefined,
        Configuration.builder()
          .baseUrl(`http://127.0.0.1:${addr.port}`)
          .build(),
      ).searchStore({ xFilter: { colour: "red", size: "a b" } });
    } finally {
      server.close();
    }

    expect(capturedHeader).toBe('{"colour":"red","size":"a b"}');
  });

  test("searchStore sends a date-time inside q in the canonical +00:00 form", async () => {
    const url = await captureSearch(
      new PhotoMetadata({ takenAt: new Date("2024-01-02T03:04:05Z") }),
    );

    expect(
      JSON.parse(new URL(url, "http://localhost").searchParams.get("q")!),
    ).toEqual({
      takenAt: "2024-01-02T03:04:05.000+00:00",
    });
  });
});

describe("StoreApi named-enum parameters", () => {
  test("bhv operations 122 getBySwatch sends the enum wire values in the path, query and header", async () => {
    // getBySwatch takes a $ref enum as a required path parameter, an optional
    // query parameter and an optional header; each must reach the wire as the
    // enum's value ('red'), never the language's enum member name.
    let capturedUrl: string | undefined;
    let capturedHeader: string | string[] | undefined;
    const server = http.createServer((req, res) => {
      capturedUrl = req.url;
      capturedHeader = req.headers["preferred-swatch"];
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end('{"id":1,"name":"swatch-category"}');
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    try {
      const addr = server.address() as { port: number };
      const swatchApi = new StoreApi(
        undefined,
        Configuration.builder()
          .baseUrl(`http://127.0.0.1:${addr.port}`)
          .build(),
      );

      const result = await swatchApi.getBySwatch(Swatch.Red, {
        querySwatch: Swatch.Green,
        preferredSwatch: Swatch.Blue,
      });

      expect(result).toBeInstanceOf(Category);
      const url = new URL(capturedUrl!, "http://localhost");
      expect(url.pathname).toBe("/store/by-swatch/red");
      expect(url.searchParams.get("querySwatch")).toBe("green");
      expect(capturedHeader).toBe("blue");
    } finally {
      server.close();
    }
  });

  test("bhv operations 107 getBySwatch omits the optional query parameter and header when they are not set", async () => {
    let capturedUrl: string | undefined;
    let capturedHeader: string | string[] | undefined;
    const server = http.createServer((req, res) => {
      capturedUrl = req.url;
      capturedHeader = req.headers["preferred-swatch"];
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end('{"id":1,"name":"swatch-category"}');
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    try {
      const addr = server.address() as { port: number };
      const swatchApi = new StoreApi(
        undefined,
        Configuration.builder()
          .baseUrl(`http://127.0.0.1:${addr.port}`)
          .build(),
      );

      await swatchApi.getBySwatch(Swatch.Blue);

      expect(capturedUrl).toBe("/store/by-swatch/blue");
      expect(capturedHeader).toBeUndefined();
    } finally {
      server.close();
    }
  });
});

describe("StoreApi error dispatch through the typed status routes", () => {
  test.each([
    [400, BadRequestError],
    [401, UnauthorizedError],
    [403, ForbiddenError],
    [404, NotFoundError],
    [409, ConflictError],
    [418, ClientError],
    [422, UnprocessableEntityError],
    [500, InternalServerError],
    [502, BadGatewayError],
  ])(
    "bhv operations 110 getOrderById picks the status-specific error for status %i",
    async (status, expected) => {
      const statusApi = new StoreApi(
        new DefaultApiClient(TransportOptions.builder().maxRetries(0).build()),
        Configuration.builder()
          .baseUrl(`${baseUrl}/test/status/${status}`)
          .build(),
      );

      const error = await statusApi.getOrderById(1).catch((e: unknown) => e);

      expect((error as Error).constructor).toBe(expected);
      expect((error as ClientError).statusCode).toBe(status);
    },
  );
});

